"""Upgrade existing tool discovery and the single RevPAR definition owner URL."""
from pathlib import Path
import re,json,xml.etree.ElementTree as E
ROOT=Path(__file__).resolve().parents[1]
DATE='2026-10-07'
def panel(s,marker,body,before='</main>'):
 block='<!-- '+marker+':start -->'+body+'<!-- '+marker+':end -->'
 pat=r'<!-- '+re.escape(marker)+r':start -->.*?<!-- '+re.escape(marker)+r':end -->'
 return re.sub(pat,lambda _:block,s,flags=re.S) if re.search(pat,s,re.S) else s.replace(before,block+before,1)
def metadata(s,title,desc):
 s=re.sub(r'<title>.*?</title>',lambda _:'<title>'+title+'</title>',s,flags=re.S)
 s=re.sub(r'(<meta (?:name="(?:description|twitter:description)"|property="og:description") content=")[^"]*',lambda m:m[1]+desc,s)
 s=re.sub(r'(<meta (?:name="twitter:title"|property="og:title") content=")[^"]*',lambda m:m[1]+title,s)
 s=re.sub(r'(property="article:modified_time" content=")[^"]*',lambda m:m[1]+DATE,s)
 def schema(m):
  g=json.loads(m[1]);items=g.get('@graph',[g]) if isinstance(g,dict) else g
  for x in items:
   if x.get('@type') in ['WebPage','Article','CollectionPage']:
    x['name']=title;x['description']=desc;x['dateModified']=DATE
    if 'headline' in x:x['headline']=title
  return '<script type="application/ld+json">'+json.dumps(g).replace('<','\\u003c')+'</script>'
 return re.sub(r'<script type="application/ld\+json">(.*?)</script>',schema,s,flags=re.S)

def build():
 p=ROOT/'tools/index.html';s=p.read_text()
 s=metadata(s,'Airbnb Investment Calculators & Buyer Tools | BNB Accelerator','Plan your Airbnb purchase cash, model rental revenue and test downside occupancy. Choose free STR calculators and verify assumptions before making an offer.')
 s=s.replace('<h1>Tools and Calculators</h1>','<h1>Airbnb investment calculators and buyer tools</h1>')
 s=re.sub(r'<p class="lead speakable-answer">.*?</p>','<p class="lead speakable-answer">Use the cash-budget calculator before searching, the revenue model when you have a specific property, and the downside calculator before committing. These tools organize assumptions; seller records, written quotes and property-specific diligence determine whether those assumptions are usable.</p>',s,flags=re.S)
 body='''<section class="bg-alt"><div class="wrap wrap-narrow"><h2>Choose the calculator for your purchase stage</h2><h3>1. Can I fund the purchase and launch?</h3><p>The <a href="/tools/first-str-purchase-budget/">first Airbnb purchase budget calculator</a> separates down payment, closing costs, furnishing, repairs, service fees and reserves. Use written lender terms and quotes. A down payment alone is not the cash required to launch a furnished rental.</p><h3>2. What can the property earn after expenses?</h3><p>The <a href="/tools/str-revenue-calculator/">short-term rental revenue calculator</a> connects nightly rate and occupancy to an expense budget. Compare the model with dated seller statements and similar properties. Keep gross booking revenue, operating profit and cash flow after financing separate.</p><h3>3. How far can performance fall before cash flow turns negative?</h3><p>The <a href="/tools/str-downside-calculator/">Airbnb downside and break-even calculator</a> tests lower occupancy and rate assumptions. Check low-season cash requirements as well as the annual total. A break-even result does not account for every repair, tax consequence or financing change.</p><h3>4. How do ADR, occupancy and RevPAR fit together?</h3><p>Use the <a href="/answers/what-is-revpar/#revpar-calculator">RevPAR formula and calculator</a> to reconcile room revenue, booked nights and available nights. A high nightly rate can coexist with lower revenue when occupancy falls. RevPAR measures revenue productivity, not profitability or investment return.</p><h2>Prepare an evidence file before trusting a model</h2><ol><li>Choose one reporting period and identify owner stays, maintenance closures and nights actually offered to guests.</li><li>Reconcile lodging revenue to monthly statements. Separate cleaning, taxes and other fees.</li><li>Record current insurance, taxes, utilities, management terms, maintenance and replacement allowances.</li><li>Get property-specific financing and closing estimates.</li><li>Run a downside case with reduced rate and occupancy, including the seasonal cash gap.</li><li>Resolve assumptions that could change the buying decision before the contractual diligence deadline.</li></ol><h2>What is a good Airbnb investment return?</h2><p>There is no universal return that proves a property is suitable. Two properties with the same revenue can require different capital, reserves and owner involvement. Judge your scenario against verified inputs, alternative uses of your capital and the loss you can absorb. None of these calculators validates a permit, loan approval or promised return.</p><p>Continue with <a href="/revenue-projections/">how to validate revenue projections</a>, <a href="/guides/reading-str-case-study-results/">how to read case study results</a>, and <a href="/done-for-you-airbnb/">the acquisition service scope</a>.</p></div></section>'''
 p.write_text(panel(s,'BUYER_TOOL_PATH',body))
 p=ROOT/'answers/what-is-revpar/index.html';s=p.read_text()
 s=metadata(s,'RevPAR Definition, Formula & STR Calculator | BNB Accelerator','RevPAR is room revenue per available night. Calculate it from revenue and availability, compare ADR and occupancy, and see why it does not measure profit.')
 s=s.replace('<h1>What Is RevPAR?</h1>','<h1>What is RevPAR? Definition, formula and calculator</h1>')
 s=re.sub(r'<p class="lead speakable-answer">.*?</p>','<p class="lead speakable-answer">RevPAR means revenue per available room, or per available rental night for a single short-term rental. Divide lodging revenue by available nights, or multiply average daily rate (ADR) by occupancy expressed as a decimal. It combines rate and occupancy but does not measure operating profit.</p>',s,flags=re.S)
 s=s.replace('$73,730','$73,584').replace('$75,190','$75,153.50')
 s=s.replace('A turns over roughly 40% less often, so its operating cost is lower and its net position may well be better despite similar RevPAR.','A has fewer booked nights, but turnover frequency also depends on length of stay. Without booking counts and expense records, neither operating cost nor net cash flow can be inferred.')
 body='''<section id="revpar-calculator"><h2>Calculate RevPAR from a revenue statement</h2><p>Enter lodging revenue only, the nights booked and the nights available for the same period. Defaults are a hypothetical 30-night example, not a market benchmark.</p><form id="revpar-form"><p><label for="room-revenue">Lodging revenue ($)</label><br><input id="room-revenue" name="revenue" type="number" min="0" step="0.01" required value="4200"></p><p><label for="booked-nights">Booked nights</label><br><input id="booked-nights" name="booked" type="number" min="0" step="1" required value="21"></p><p><label for="available-nights">Available nights</label><br><input id="available-nights" name="available" type="number" min="1" step="1" required value="30"></p><button class="btn btn-primary" type="submit">Calculate RevPAR</button></form><p id="revpar-result" role="status" aria-live="polite">Example: $4,200 ÷ 30 available nights = $140 RevPAR; $4,200 ÷ 21 booked nights = $200 ADR; 21 ÷ 30 = 70% occupancy.</p><noscript><p>Use the formulas above to calculate manually. The example and guidance remain available without JavaScript.</p></noscript><h3>Which revenue belongs in the numerator?</h3><p>Use a consistent lodging-revenue basis. Do not silently combine nightly accommodation revenue with guest-paid taxes, cleaning charges or deposits. If a statement reports total guest payments, reconcile those components first. Record whether the figure is before or after platform fees and refunds so comparisons use the same basis.</p><h3>What counts as an available night?</h3><p>Document the denominator. For an operating-performance calculation, use the nights genuinely available for rental and record nights excluded for owner use or maintenance. For a purchase review, also test revenue over the full calendar period. Reducing the denominator can raise reported RevPAR without adding revenue or reducing fixed carrying costs.</p><h3>Example: a blocked calendar changes the apparent result</h3><p>A hypothetical property earns $4,200 on 21 booked nights in a 30-night month. With 30 available nights it reports $140 RevPAR. If six unbooked nights are excluded as owner use, the denominator becomes 24 and reported RevPAR rises to $175. The owner still received the same lodging revenue. Label both calculations; do not compare the 24-night result with another property's full-calendar result.</p><h3>Can I average monthly RevPAR?</h3><p>Weight periods by available nights. Suppose a property earns $3,100 across 31 available nights and $5,600 across 28. Combined RevPAR is $8,700 ÷ 59 = $147.46. The simple average of monthly results ($100 and $200) is $150 and overstates the combined figure. Apply the same reconciliation across multiple units using available room-nights.</p><h3>How should a buyer use RevPAR?</h3><p>Compare similar property types over the same season with the same revenue and availability definitions. Investigate whether a stronger result comes from rate, occupancy or calendar exclusions. Then build the full expense and financing model. RevPAR alone cannot establish a purchase price, reserve requirement or cash-on-cash return.</p><p>Use the <a href="/tools/">buyer calculator sequence</a>, <a href="/tools/str-downside-calculator/">downside model</a> and <a href="/revenue-projections/">revenue evidence guide</a> before relying on a seller projection.</p></section>'''
 s=panel(s,'REVPAR_WORKSHEET',body,'<h2 id="formula">')
 s=panel(s,'REVPAR_SCRIPT','<script src="/assets/revpar-calculator.js" defer></script>','</body>')
 p.write_text(s)
 tree=E.parse(ROOT/'sitemap-core.xml');ns='{http://www.sitemaps.org/schemas/sitemap/0.9}'
 for row in tree.getroot():
  if row.find(ns+'loc').text in ['https://www.bnbaccelerator.com/tools/','https://www.bnbaccelerator.com/answers/what-is-revpar/']:
   lm=row.find(ns+'lastmod')
   if lm is None:lm=E.SubElement(row,ns+'lastmod')
   lm.text=DATE
 E.indent(tree);tree.write(ROOT/'sitemap-core.xml',encoding='utf-8',xml_declaration=True)
 print('Buyer tools hub and RevPAR owner page updated.')
if __name__=='__main__':build()
